fn ascii_toupper(b: u8) -> u8 {
    if b.is_ascii_lowercase() { b - 32 } else { b }
}

/// line 3: camelize(word)  — default 2nd parameter
pub fn camelize_lower(input: &str) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    let mut cap = false;
    for &c in input.as_bytes() {
        if c == b'_' {
            cap = true;
        } else if cap {
            out.push(ascii_toupper(c));
            cap = false;
        } else {
            out.push(c);
        }
    }
    // Bytes >= 0x80 are passed through untouched, so any UTF-8 that survived
    // in the input is still valid UTF-8 here.
    unsafe { String::from_utf8_unchecked(out) }
}

/// line 4: camelize(word, false)
pub fn camelize_upper(input: &str) -> String {
    let mut out: Vec<u8> = camelize_lower(input).into_bytes();
    if let Some(first) = out.first_mut() {
        *first = ascii_toupper(*first);   // first BYTE only; no-op if not b'a'..=b'z'
    }
    unsafe { String::from_utf8_unchecked(out) }
}
